{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Depression is a very common psychiatric disorder in worldwide. Globally, Human Immunodeficiency Virus (HIV) is highly prevalent among women, and are disproportionately affected by depression... However, it is not well understood specifically how depression affects ART adherence in women living with HIV (WLWHIV).",
      "reason": "The Background describes current knowledge (depression common, HIV prevalent among women) and the uncertainty (how depression affects ART adherence in WLWHIV is not well understood)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Antiretroviral Therapy (ART) adherence which could highly be affected by depression is yet to be explored effectively... Investigating the effects of depression on ART adherence is critical in order to develop nuanced new evidence to address non-adherence in WLWHIV.",
      "reason": "The need and importance of the review are explicitly stated (area yet to be explored; investigation is critical to develop new evidence)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of prior similar systematic reviews being cited or discussed; the topic is described as an 'untouched area of research' (text_25), so no update/replication justification is required."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of the effect of depression (exposure) on ART adherence, not a review of an intervention's effects, so a mechanism of action description does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines an exposure-outcome association, not a complex intervention or delivery context, so a logic model is not applicable."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "To conduct a meta-analysis on the correlation between depression and adherence to antiretroviral therapy among women living with HIV in the globe.",
      "reason": "A dedicated 'Objective' section explicitly states the review objective, and it is framed with the components of a relevant question framework (PEO): population (women living with HIV), exposure (depression), and outcome (adherence to antiretroviral therapy). This is corroborated by text_5, which states the search used a 'population, exposed and outcome approach', confirming the PEO structure of the review question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "Using population, exposed and outcome approach, we searched Scopus, PubMed, EMBASE, Cochrane Library, Psych info, Web of science and google scholar for cohort and cross-sectional studies globally.",
      "reason": "The review examines the association between an exposure (depression) and an outcome (ART adherence) using cohort and cross-sectional observational studies, reporting RR and AOR (text_19), not the effects of an intervention. Since this is not a review of intervention effects, the requirement to state planned comparisons using PICO does not apply."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Inclusion criteria. Peer reviewed cross-sectional and cohort study designed from across the world, published in English from 1 January 2000 to 30 December 2022 were included in the final analysis. Cross-sectional studies reporting an association between depression and ART adherence and cohort studies reporting the effect of depression on ART adherence were included.",
      "reason": "Population (women living with HIV, text_11 PEO), exposure, outcome, designs, and setting (global) are specified, but no follow-up duration requirements are reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Peer reviewed cross-sectional and cohort study designed from across the world, published in English from 1 January 2000 to 30 December 2022 were included",
      "reason": "Dissemination year range, language (English), and publication status (peer reviewed) are all specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_18",
      "quote": "four articles after reviewed full article (two articles stated the effect of depression on death, one article dealt with stress, and one article was due to small sample size(n = 13), and they were excluded",
      "reason": "Exclusion reasons are given for full texts, but the review never distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "In systematic review, the studies reported in a cross-sectional study design and effect of depression on ART adherence in cohort study design were included. For meta-analysis, only cohort study findings were included because it showed cause and effect relationship between depression and ART adherence in WLWHIV.",
      "reason": "Synthesis groups (cohort studies in meta-analysis; cross-sectional studies in narrative synthesis) are specified and linked to the review objective of the effect of depression on ART adherence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "only cohort study findings were included because it showed cause and effect relationship between depression and ART adherence in WLWHIV. However, in cross-sectional study design either depression has effect on ART adherence or vice versa could not be known.",
      "reason": "A rationale is given for restricting the meta-analysis to cohort studies, but other notable restrictions (e.g., English-only, excluding perinatal/postnatal women) lack explicit rationale in the methods; English-only rationale appears only in limitations (text_25)."
    }
  ],
  "confidence": 88
}

